621	    return;
622	  }
623	
624	  // Sort by score descending
625	  const scoreKey = getScoreField();
626	  const rankKey = gameData.hasLanes ? (currentMethod === "zscore" ? "_rank_zscore" : "_rank_simple") : "rank";
627	  results.sort((a, b) => b[scoreKey] - a[scoreKey]);
628	  // Set laneRank for display
