639	      { label: "评分", field: "score", type: "score" },
640	      { label: "胜率", field: "wr", type: "pct", colorClass: "wr" },
641	      { label: "出场率", field: "pr", type: "pct" },
642	      { label: "Ban率", field: "br", type: "pct" },
