    normalize(allHeroes, "raw_zscore", "score_zscore_global");
    normalize(allHeroes, "raw_simple", "score_simple_global");

    // Assign tiers
    for (const [, heroes] of Object.entries(lanes)) {
        assignTiersWithKey(heroes, "score_zscore", "tier_zscore");
        assignTiersWithKey(heroes, "score_simple", "tier_simple");
        assignTiersWithKey(heroes, "score_zscore_global", "tier_global");
    }

    // Global ranking
    const globalZ = [...allHeroes].sort((a, b) => b.score_zscore_global - a.score_zscore_global);
    globalZ.forEach((h, i) => { h.global_rank_zscore = i + 1; });
    const globalSimple = [...allHeroes].sort((a, b) => b.score_simple_global - a.score_simple_global);
    globalSimple.forEach((h, i) => { h.global_rank_simple = i + 1; });

    return { lanes, allHeroes, globalZ, globalSimple };
}

function computeSG(rawData) {
    const heroes = rawData.map(h => ({
        name: h.heroName,
        headIcon: gameConfig.headIconPath ? ("曙光英雄/" + gameConfig.headIconPath.replace("{name}", h.heroName)) : null,
        appearanceRank: parseInt(h.appearanceRank),
        combatPower: parseFloat(h.combatPower),
        winRate: parseFloat(String(h.winRate).replace("%", "")) / 100,
        lane: null
    }));

    const N = heroes.length;
    const weights = gameConfig.algorithm.weights;

    const appearanceScores = heroes.map(h => 1 - (h.appearanceRank - 1) / (N - 1));
    const combatVals = heroes.map(h => h.combatPower);
    const combatMin = Math.min(...combatVals), combatMax = Math.max(...combatVals);
    const combatRange = combatMax - combatMin || 1;
    const combatScores = combatVals.map(v => (v - combatMin) / combatRange);
    const wrVals = heroes.map(h => h.winRate);
    const wrMin = Math.min(...wrVals), wrMax = Math.max(...wrVals);
    const wrRange = wrMax - wrMin || 1;
    const wrScores = wrVals.map(v => (v - wrMin) / wrRange);

    heroes.forEach((h, i) => {
        h.raw_weighted = weights.appearance * appearanceScores[i]
                       + weights.combat * combatScores[i]
                       + weights.winrate * wrScores[i];
    });

    const rawVals = heroes.map(h => h.raw_weighted);
    const rawMin = Math.min(...rawVals), rawMax = Math.max(...rawVals);
    const rawRange = rawMax - rawMin || 1;
    heroes.forEach(h => { h.score = ((h.raw_weighted - rawMin) / rawRange) * 100; });

    const sorted = [...heroes].sort((a, b) => b.score - a.score);
    const thresholds = getTierThresholds();
    sorted.forEach((h, i) => {
        const pct = 1 - i / N;
        let tier = "T4";
        for (const t of thresholds) {
            if (pct >= t.pct) { tier = t.tier; break; }
        }
        h.tier = tier;
        h.rank = i + 1;
    });

    return { heroes, sorted };
}

// ---- Render ----
function renderGridView(heroes, highlightLane) {
    const tierOrder = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
    const colors = getTierColors();
    const groups = {};
    tierOrder.forEach(t => { groups[t] = []; });

    heroes.forEach(h => {
        const tier = gameConfig.hasLanes ? h[getTierField(h)] : h.tier;
        if (groups[tier]) groups[tier].push(h);
        else { groups["T4"] = groups["T4"] || []; groups["T4"].push(h); }
    });

    const scoreKey = getScoreField();
    tierOrder.forEach(t => {
        if (groups[t]) groups[t].sort((a, b) => b[scoreKey] - a[scoreKey]);
    });

    return { groups, scoreKey };
}

// ===== TEST LoLM =====
console.log("=".repeat(60));
console.log("TEST 1: LoLM - 上路 lane view (grid)");
console.log("=".repeat(60));

gameConfig = config;
const rawDataLOLM = { '上路': top, '打野': jg, '中路': mid, '下路': adc, '辅助': sup };
const lolmData = computeLOLM(rawDataLOLM);

gameData = {
    hasLanes: true,
    lanes: {},
    allHeroes: lolmData.allHeroes,
    globalZ: lolmData.globalZ,
    globalSimple: lolmData.globalSimple
};
for (const [name, heroes] of Object.entries(lolmData.lanes)) {
    gameData.lanes[name] = heroes;
}

currentLane = "上路";
currentMethod = "zscore";
currentView = "lane";

const laneHeroes = gameData.lanes[currentLane];
console.log(`laneHeroes length: ${laneHeroes.length}`);

// Check tier_zscore values
const tierCounts = {};
laneHeroes.forEach(h => {
    const tier = h.tier_zscore;
    tierCounts[tier] = (tierCounts[tier] || 0) + 1;
});
console.log("tier_zscore distribution:", tierCounts);

// Render grid
const result = renderGridView(laneHeroes, null);
console.log("\nGrid groups:");
for (const [tier, heroes] of Object.entries(result.groups)) {
    const names = heroes.map(h => h.name);
    console.log(`  ${tier} (${heroes.length}): ${names.join(', ')}`);
}

// Check for 无双剑姬 duplicates in any group
console.log("\n=== Duplicate check ===");
const allNamesInGrid = [];
for (const heroes of Object.values(result.groups)) {
    for (const h of heroes) {
        allNamesInGrid.push(h.name);
    }
}
const dupes = allNamesInGrid.filter((name, idx) => allNamesInGrid.indexOf(name) !== idx);
console.log(`Total heroes rendered: ${allNamesInGrid.length}`);
console.log(`Duplicate names: ${[...new Set(dupes)].join(', ') || 'NONE'}`);
console.log(`无双剑姬 count: ${allNamesInGrid.filter(n => n === '无双剑姬').length}`);
console.log(`狂暴之心 count: ${allNamesInGrid.filter(n => n === '狂暴之心').length}`);
console.log(`纳祖芒荣耀 tier: ${laneHeroes.find(h => h.name === '纳祖芒荣耀').tier_zscore}`);


// ===== TEST LoLM - global view (grid) =====
console.log("\n" + "=".repeat(60));
console.log("TEST 2: LoLM - global view (grid)");
console.log("=".repeat(60));

currentView = "global";
const globalHeroes = currentMethod === "zscore" ? gameData.globalZ : gameData.globalSimple;
console.log(`globalHeroes length: ${globalHeroes.length}`);

const globalResult = renderGridView(globalHeroes, null);
console.log("\nGlobal Grid groups:");
for (const [tier, heroes] of Object.entries(globalResult.groups)) {
    console.log(`  ${tier} (${heroes.length} heroes)`);
}

// Check dupes in global
const globalAllNames = [];
for (const heroes of Object.values(globalResult.groups)) {
    for (const h of heroes) {
        globalAllNames.push(h.name);
    }
}
console.log(`\nTotal global heroes rendered: ${globalAllNames.length}`);
console.log(`无双剑姬 count: ${globalAllNames.filter(n => n === '无双剑姬').length}`);
console.log(`狂暴之心 count: ${globalAllNames.filter(n => n === '狂暴之心').length}`);

// ===== TEST SG =====
console.log("\n" + "=".repeat(60));
console.log("TEST 3: 曙光英雄 - grid view");
console.log("=".repeat(60));

gameConfig = sgConfig;
currentMethod = "weighted";
const sgResult = computeSG(sgData);
gameData = { hasLanes: false, heroes: sgResult.heroes, sorted: sgResult.sorted };

const sgGridResult = renderGridView(gameData.heroes, null);
console.log("\nSG Grid groups:");
for (const [tier, heroes] of Object.entries(sgGridResult.groups)) {
    console.log(`  ${tier} (${heroes.length} heroes)`);
}

const sgAllNames = [];
for (const heroes of Object.values(sgGridResult.groups)) {
    for (const h of heroes) {
        sgAllNames.push(h.name);
    }
}
const sgDupes = sgAllNames.filter((name, idx) => sgAllNames.indexOf(name) !== idx);
console.log(`\nTotal SG heroes rendered: ${sgAllNames.length}`);
console.log(`SG input heroes: ${gameData.heroes.length}`);
console.log(`Duplicate names: ${[...new Set(sgDupes)].length > 0 ? [...new Set(sgDupes)].slice(0,5).join(', ') + '...' : 'NONE'}`);

