// Generate actual HTML output as browser would see it
"use strict";

const fs = require('fs');

// ---- Same functions as tierlist.js ----
function parsePct(s) {
    if (typeof s === "number") return s / 100;
    return parseFloat(String(s).replace("%", "")) / 100;
}
function mean(arr) { return arr.reduce((a, b) => a + b, 0) / arr.length; }
function stdDev(arr) {
    const m = mean(arr);
    const v = arr.reduce((s, v) => s + (v - m) ** 2, 0) / arr.length;
    return Math.sqrt(v) || 1;
}
function zScores(arr) {
    const m = mean(arr);
    const s = stdDev(arr);
    if (s === 0) return arr.map(() => 0);
    return arr.map(v => (v - m) / s);
}

// ---- Load data ----
const top = JSON.parse(fs.readFileSync('lolm/上路.json', 'utf8'));
const jg = JSON.parse(fs.readFileSync('lolm/打野.json', 'utf8'));
const mid = JSON.parse(fs.readFileSync('lolm/中路.json', 'utf8'));
const adc = JSON.parse(fs.readFileSync('lolm/下路.json', 'utf8'));
const sup = JSON.parse(fs.readFileSync('lolm/辅助.json', 'utf8'));
const config = JSON.parse(fs.readFileSync('lolm/config.json', 'utf8'));

// ---- State ----
let gameConfig = config;
let gameData = null;
let currentMethod = "zscore";
let currentView = "lane";
let currentLane = null;

function getScoreField(hero) {
    if (gameConfig.hasLanes) {
        return currentMethod === "zscore" ? "score_zscore" : "score_simple";
    }
    return "score";
}

function getTierField(hero) {
    if (gameConfig.hasLanes) {
        return currentMethod === "zscore" ? "tier_zscore" : "tier_simple";
    }
    return "tier";
}

function getTierThresholds() { return gameConfig.tiers.thresholds; }
function getTierColors() { return gameConfig.tiers.colors; }

function assignTiersWithKey(heroes, scoreKey, tierKey) {
    const sorted = [...heroes].sort((a, b) => b[scoreKey] - a[scoreKey]);
    const n = sorted.length;
    const thresholds = getTierThresholds();
    sorted.forEach((h, i) => {
        const pct = 1 - i / n;
        let tier = "T4";
        for (const t of thresholds) {
            if (pct >= t.pct) { tier = t.tier; break; }
        }
        h[tierKey] = tier;
        if (tierKey === "tier_zscore") h._rank_zscore = i + 1;
        if (tierKey === "tier_simple") h._rank_simple = i + 1;
    });
}

function computeLOLM(rawData) {
    const lanes = {};
    const allHeroes = [];
    for (const laneCfg of gameConfig.lanes) {
        const raw = rawData[laneCfg.name];
        if (!raw) continue;
        const heroes = raw.map(h => ({
            name: h.heroName,
            lane: laneCfg.name,
            headIcon: gameConfig.headIconPath ? (gameConfig.gameId + "/" + gameConfig.headIconPath.replace("{name}", h.heroName)) : null,
            wr: parsePct(h.winRate),
            pr: parsePct(h.pickRate),
            br: parsePct(h.banRate),
            bp: parsePct(h.pickRate) + parsePct(h.banRate)
        }));
        lanes[laneCfg.name] = heroes;
        allHeroes.push(...heroes);
    }
    for (const [laneName, heroes] of Object.entries(lanes)) {
        const zWr = zScores(heroes.map(h => h.wr));
        const zPr = zScores(heroes.map(h => h.pr));
        const zBr = zScores(heroes.map(h => h.br));
        heroes.forEach((h, i) => {
            h.z_wr = zWr[i]; h.z_pr = zPr[i]; h.z_br = zBr[i];
            h.raw_zscore = 0.5 * zWr[i] + 1.0 * zPr[i] + 3.0 * zBr[i];
        });
    }
    for (const [laneName, heroes] of Object.entries(lanes)) {
        heroes.forEach(h => {
            h.raw_simple = Math.pow(h.wr, 0.3) * (h.pr + 2.5 * h.br) * 100;
        });
    }
    function normalize(heroes, rawKey, normKey) {
        const vals = heroes.map(h => h[rawKey]);
        const lo = Math.min(...vals), hi = Math.max(...vals);
        const rng = hi - lo || 1;
        heroes.forEach(h => { h[normKey] = ((h[rawKey] - lo) / rng) * 100; });
    }
    for (const [, heroes] of Object.entries(lanes)) {
        normalize(heroes, "raw_zscore", "score_zscore");
        normalize(heroes, "raw_simple", "score_simple");
    }
    normalize(allHeroes, "raw_zscore", "score_zscore_global");
    normalize(allHeroes, "raw_simple", "score_simple_global");
    for (const [, heroes] of Object.entries(lanes)) {
        assignTiersWithKey(heroes, "score_zscore", "tier_zscore");
        assignTiersWithKey(heroes, "score_simple", "tier_simple");
        assignTiersWithKey(heroes, "score_zscore_global", "tier_global");
    }
    const globalZ = [...allHeroes].sort((a, b) => b.score_zscore_global - a.score_zscore_global);
    globalZ.forEach((h, i) => { h.global_rank_zscore = i + 1; });
    const globalSimple = [...allHeroes].sort((a, b) => b.score_simple_global - a.score_simple_global);
    globalSimple.forEach((h, i) => { h.global_rank_simple = i + 1; });
    return { lanes, allHeroes, globalZ, globalSimple };
}

// ---- Render grid view (exact copy from tierlist.js) ----
function renderGridView(heroes, highlightLane) {
    const tierOrder = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
    const colors = getTierColors();
    const groups = {};
    tierOrder.forEach(t => { groups[t] = []; });

    heroes.forEach(h => {
        const tier = gameConfig.hasLanes ? h[getTierField(h)] : h.tier;
        if (groups[tier]) groups[tier].push(h);
        else { groups["T4"] = groups["T4"] || []; groups["T4"].push(h); }
    });

    const scoreKey = getScoreField();
    tierOrder.forEach(t => {
        if (groups[t]) groups[t].sort((a, b) => b[scoreKey] - a[scoreKey]);
    });

    let html = '<div class="tier-grid">\n';
    tierOrder.forEach(t => {
        const list = groups[t] || [];
        const color = colors[t] || "#8c8c8c";
        html += `  <div class="tier-row${list.length === 0 ? " tier-row-empty" : ""}">\n`;
        html += `    <div class="tier-label" style="background:${color}">${t}</div>\n`;
        html += '    <div class="tier-icons">\n';
        if (list.length === 0) {
            html += '      <span>暂无英雄</span>\n';
        } else {
            list.forEach(h => {
                const name = h.name;
                html += `      <div class="tier-hero" title="${name}" data-tier="${h[getTierField(h)] || h.tier || 'undefined'}" data-score="${h[getScoreField(h)]}">\n`;
                if (h.headIcon) {
                    html += `        <img src="${h.headIcon}" alt="${name}" loading="lazy" onerror="this.style.display='none'">\n`;
                } else {
                    html += `        <div class="hero-icon-placeholder"></div>\n`;
                }
                html += `        <span class="tier-hero-name">${name}</span>\n`;
                html += '      </div>\n';
            });
        }
        html += '    </div>\n';
        html += '  </div>\n';
    });
    html += '</div>';
    return html;
}

// ---- Simulate page load ----
const rawData = { '上路': top, '打野': jg, '中路': mid, '下路': adc, '辅助': sup };
const lolmData = computeLOLM(rawData);
gameData = { hasLanes: true, lanes: {}, allHeroes: lolmData.allHeroes, globalZ: lolmData.globalZ, globalSimple: lolmData.globalSimple };
for (const [name, heroes] of Object.entries(lolmData.lanes)) {
    gameData.lanes[name] = heroes;
}
currentLane = "上路";

// Render lane grid
const laneHtml = renderGridView(gameData.lanes["上路"], null);
console.log("=== 上路 Lane Grid HTML ===");
console.log(laneHtml);

// Count heroes in each tier from HTML
console.log("\n=== HTML中每梯度英雄数 ===");
const tierMatches = laneHtml.match(/data-tier="([^"]+)"/g);
if (tierMatches) {
    const counts = {};
    tierMatches.forEach(m => {
        const tier = m.match(/data-tier="([^"]+)"/)[1];
        counts[tier] = (counts[tier] || 0) + 1;
    });
    for (const [t, c] of Object.entries(counts)) {
        console.log(`  ${t}: ${c}`);
    }
}

// Check for dup names in T4
const t4Section = laneHtml.match(/<div class="tier-label[^"]*" style="background:#8c8c8c">T4<\/div>[\s\S]*?(?=<div class="tier-row|$)/);
if (t4Section) {
    const names = t4Section[0].match(/<span class="tier-hero-name">([^<]+)<\/span>/g);
    if (names) {
        const nameList = names.map(n => n.replace(/<[^>]+>/g, ''));
        console.log(`\n=== T4 HTML中的英雄 ===`);
        nameList.forEach((n, i) => console.log(`  ${i+1}. ${n}`));
        const dupCheck = {};
        nameList.forEach(n => { dupCheck[n] = (dupCheck[n] || 0) + 1; });
        const dups = Object.entries(dupCheck).filter(([k,v]) => v > 1);
        if (dups.length) {
            console.log(`\n!!! T4中发现重复: ${dups.map(([k,v]) => `${k}x${v}`).join(', ')}`);
        } else {
            console.log(`\nT4中无重复 ✓`);
        }
    }
}

// Now render the FULL page as it would appear (titleHtml + grid)
const titleHtml = `<div class="section-header">
    <h2>上路</h2>
    <span class="count-badge">38 个英雄</span></div>`;

const fullPageHtml = titleHtml + laneHtml;
fs.writeFileSync('test_output.html', fullPageHtml, 'utf8');
console.log("\n=== Full HTML written to test_output.html ===");
console.log(`Total HTML size: ${fullPageHtml.length} bytes`);

