// Test 4: SG
const sgConfig = JSON.parse(fs.readFileSync('曙光英雄/config.json', 'utf8'));
const sgRaw = JSON.parse(fs.readFileSync('曙光英雄/曙光英雄.json', 'utf8'));
gameConfig = sgConfig;
currentMethod = 'weighted';

// Simplified SG compute
