/* ============================================================
   英雄梯度排行榜 — 公共样式
   适配 LOLM 和 曙光英雄，深色主题，响应式
   ============================================================ */

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC",
                 "Microsoft YaHei", sans-serif;
    background: #0d1117;
    color: #c9d1d9;
    min-height: 100vh;
}

/* ---- 头部 ---- */
.header {
    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
    padding: 24px 24px 20px;
    text-align: center;
    border-bottom: 1px solid #30363d;
}
.header h1 { font-size: 1.8rem; color: #f0f6fc; margin-bottom: 4px; }
.header .subtitle {
    font-size: 0.85rem; color: #8b949e; margin-top: 4px;
}

/* ---- 游戏选择器 ---- */
.game-selector {
    display: flex; justify-content: center; gap: 8px;
    margin-top: 16px; flex-wrap: wrap;
}
.game-selector button {
    background: rgba(255,255,255,0.06);
    color: #8b949e; border: 1px solid #30363d;
    padding: 10px 28px; border-radius: 8px; cursor: pointer;
    font-size: 0.95rem; transition: all 0.25s;
    display: flex; align-items: center; gap: 8px;
}
.game-selector button:hover {
    background: rgba(255,255,255,0.10); color: #c9d1d9;
    border-color: #484f58;
}
.game-selector button.active {
    background: #1f6feb; border-color: #1f6feb; color: #fff;
    box-shadow: 0 0 12px rgba(31,111,235,0.3);
}
.game-selector .game-badge {
    font-size: 0.7rem; background: rgba(255,255,255,0.15);
    padding: 1px 6px; border-radius: 3px;
}

/* ---- 导航栏 ---- */
.nav {
    display: flex; justify-content: center; gap: 4px;
    padding: 12px 24px; background: #161b22;
    border-bottom: 1px solid #30363d; position: sticky; top: 0; z-index: 100;
    flex-wrap: wrap;
}
.nav button {
    background: #21262d; color: #c9d1d9; border: 1px solid #30363d;
    padding: 7px 18px; border-radius: 6px; cursor: pointer;
    font-size: 0.88rem; transition: all 0.2s;
}
.nav button:hover { background: #30363d; }
.nav button.active { background: #1f6feb; border-color: #1f6feb; color: #fff; }
.nav .hero-count { color: #8b949e; font-size: 0.8rem; align-self: center; margin-left: 8px; }

/* ---- 控制栏 ---- */
.controls {
    display: flex; justify-content: center; align-items: center; gap: 16px;
    padding: 12px 24px; flex-wrap: wrap;
}
.controls .label { color: #8b949e; font-size: 0.8rem; margin-right: 2px; }
.controls button {
    background: transparent; color: #8b949e; border: 1px solid #30363d;
    padding: 5px 14px; border-radius: 4px; cursor: pointer; font-size: 0.8rem;
    transition: all 0.2s;
}
.controls button:hover { border-color: #484f58; color: #c9d1d9; }
.controls button.active { background: #238636; border-color: #238636; color: #fff; }

/* ---- 内容区 ---- */
.container { max-width: 1280px; margin: 0 auto; padding: 24px; }

.section-header {
    display: flex; align-items: center; gap: 12px;
    margin-bottom: 20px; padding-bottom: 12px; border-bottom: 1px solid #30363d;
    flex-wrap: wrap;
}
.section-header h2 { font-size: 1.5rem; color: #f0f6fc; }
.section-header .count-badge {
    color: #8b949e; font-size: 0.9rem; background: #21262d;
    padding: 2px 10px; border-radius: 10px;
}
.section-header .hint {
    color: #8b949e; font-size: 0.85rem; margin-left: auto;
}

/* ---- 统计卡片 ---- */
.stats-row { display: flex; gap: 12px; margin-bottom: 20px; flex-wrap: wrap; }
.stat-card {
    background: #161b22; border: 1px solid #30363d; border-radius: 8px;
    padding: 12px 16px; flex: 1; min-width: 100px; text-align: center;
}
.stat-card .stat-value { font-size: 1.4rem; font-weight: 700; color: #f0f6fc; }
.stat-card .stat-label { font-size: 0.75rem; color: #8b949e; margin-top: 2px; }

/* ---- 表格 ---- */
.table-wrapper { overflow-x: auto; border-radius: 8px; border: 1px solid #30363d; }
table { width: 100%; border-collapse: collapse; font-size: 0.9rem; }
thead th {
    background: #161b22; color: #8b949e; padding: 12px 14px;
    text-align: left; font-weight: 600; border-bottom: 1px solid #30363d;
    white-space: nowrap; position: sticky; top: 0; cursor: pointer; user-select: none;
}
thead th:hover { color: #f0f6fc; }
thead th .sort-icon { opacity: 0.3; margin-left: 4px; }
thead th.sorted .sort-icon { opacity: 1; }
tbody td { padding: 10px 14px; border-bottom: 1px solid #21262d; }
tbody tr:hover { background: rgba(255,255,255,0.03); }
tbody tr.current-highlight { background: rgba(31,111,235,0.08); }

/* ---- 排名数字 ---- */
.rank-num { font-weight: 700; font-size: 1rem; color: #f0f6fc; text-align: center; }
.rank-1 { color: #ffd700; font-size: 1.3rem; }
.rank-2 { color: #c0c0c0; font-size: 1.2rem; }
.rank-3 { color: #cd7f32; font-size: 1.1rem; }

/* ---- 梯度标签 ---- */
.tier-badge {
    display: inline-block; padding: 3px 10px; border-radius: 4px;
    font-weight: 700; font-size: 0.8rem; color: #fff; text-align: center; min-width: 44px;
}

/* ---- 分数条 ---- */
.score-bar-wrap { display: flex; align-items: center; gap: 8px; min-width: 120px; }
.score-bar { flex: 1; height: 6px; background: #21262d; border-radius: 3px; overflow: hidden; }
.score-bar-fill { height: 100%; border-radius: 3px; transition: width 0.3s; }
.score-value { font-weight: 600; font-size: 0.85rem; color: #f0f6fc; min-width: 44px; text-align: right; }

/* ---- 英雄名 + 头像 ---- */
.hero-name { font-weight: 600; color: #f0f6fc; }
.hero-cell { display: flex; align-items: center; gap: 8px; }
.hero-icon {
    width: 32px; height: 32px; border-radius: 50%;
    border: 1.5px solid #30363d; object-fit: cover;
    background: #21262d; flex-shrink: 0;
}

/* ---- 高亮色 ---- */
.wr-high { color: #3fb950; font-weight: 600; }
.wr-mid { color: #d29922; }
.wr-low { color: #f85149; }
.cw-high { color: #3fb950; font-weight: 600; }
.cw-mid { color: #d29922; }
.cw-low { color: #f85149; }

/* ---- 搜索框 ---- */
.search-box {
    background: #21262d; border: 1px solid #30363d; border-radius: 6px;
    padding: 8px 14px; color: #c9d1d9; font-size: 0.9rem; width: 200px;
    outline: none; transition: border-color 0.2s;
}
.search-box:focus { border-color: #1f6feb; }
.search-box::placeholder { color: #484f58; }

/* ---- 页脚 ---- */
.footer {
    text-align: center; padding: 24px; color: #484f58;
    font-size: 0.8rem; border-top: 1px solid #30363d; margin-top: 24px;
}

/* ---- 梯度网格视图 ---- */
.tier-grid {
    display: flex; flex-direction: column;
    gap: 3px; background: #000; padding: 3px;
    border-radius: 8px; overflow: hidden;
    border: 1px solid #30363d; min-width: 320px;
}
.tier-row {
    display: flex; flex-direction: row; min-height: 64px;
    background: #161b22;
}
.tier-label {
    display: flex; align-items: center; justify-content: center;
    width: 64px; min-width: 64px; font-weight: 800; font-size: 1.1rem;
    color: #fff; text-shadow: 0 1px 3px rgba(0,0,0,0.5);
    letter-spacing: 1px; user-select: none;
}
.tier-icons {
    display: flex; flex-wrap: wrap; gap: 6px;
    padding: 8px 12px; align-items: center; flex: 1;
    background: #0d1117;
}
.tier-hero {
