    .tier-hero-img-wrap { width: 38px; height: 38px; }
    .tier-hero img { width: 38px; height: 38px; }
    .tier-hero .tier-hero-name { font-size: 0.5rem; padding: 1px 1px 2px; }
    .tier-row { min-height: 48px; }
}

